<script lang="ts">
 import { onMount } from 'svelte';
 import { concepts } from '$lib/data/concepts';
 let { slug, title }: { slug: string; title: string } = $props();
 const concept = $derived(concepts[slug]);
 let step = $state(0);
 let playing = $state(true);
 let visible = $state(false);
 let stage: HTMLElement;
 let reduced = false;
 function next() { playing = false; step = (step + 1) % 4; }
 function replay() { step = 0; playing = !reduced; }
 function toggle() { if (!playing && step === 3) step = 0; playing = !playing && !reduced; }
 onMount(() => {
  const preference = matchMedia('(prefers-reduced-motion: reduce)');
  const update = () => { reduced = preference.matches; if (reduced) playing = false; };
  update(); preference.addEventListener('change', update);
  const observer = new IntersectionObserver(entries => { visible = entries[0].isIntersecting; }, { threshold: .35 });
  observer.observe(stage);
  const timer = setInterval(() => {
   if (!visible || !playing || reduced || document.hidden || document.documentElement.classList.contains('motion-paused')) return;
   if (step < 3) step += 1; else playing = false;
  }, 2600);
  return () => { observer.disconnect(); clearInterval(timer); preference.removeEventListener('change', update); };
 });
</script>

<section bind:this={stage} class="concept {slug}" class:stopped={!playing || !visible} aria-label={`${title} concept demo`}>
 <div class="scene-top"><span>CONCEPT DEMO · SAMPLE DATA</span><span class="counter">0{step + 1} / 04</span></div>
 <div class="stage">
  <div class="scene-heading"><h4>{concept.label}</h4><div class="steps" aria-label="Demo progress">{#each concept.steps as label, i}<button class:active={step === i} class:done={step > i} aria-label={`Show step ${i + 1}: ${label}`} aria-pressed={step === i} onclick={() => { step = i; playing = false; }}><span>{step > i ? '✓' : i + 1}</span>{label}</button>{/each}</div></div>
  <div class="product" class:phone={slug === 'clearpoint' && step === 3}>
   <div class="appbar"><span class="dots" aria-hidden="true">● ● ●</span><span>{title}</span><span class="status">{concept.steps[step]}</span></div>
   {#if slug === 'chat-cms'}
    <div class="split"><div class="chat"><span class="micro">SITE ASSISTANT</span><div class="bubble user">Change Saturday hours to 9-5.</div>{#if step >= 1}<div class="bubble assistant">Found the Hours page.<br/><strong>✓ Update is allowed</strong></div>{/if}{#if step >= 2}<div class="bubble assistant">Saturday: <s>10am-4pm</s><br/><strong>9am-5pm</strong></div>{/if}<div class="composer">Ask for a change <span>↑</span></div></div><div class="site-preview"><div class="tiny-nav">BRAVE LIZARD <span>VISIT ↗</span></div><div class="range-art" aria-hidden="true"><i></i><i></i><i></i></div><h5>Make time<br/>for the range.</h5><div class="hours" class:changed={step >= 2}><span>SATURDAY</span><strong>{step >= 2 ? '9am - 5pm' : '10am - 4pm'}</strong></div><span class="pill">{step === 3 ? '✓ Published · Activity logged' : step === 2 ? 'Preview · Not published yet' : 'Current page'}</span></div></div>
   {:else if slug === 'seo-pipeline'}
    <div class="seo-layout"><aside><span class="micro">SITE HEALTH</span><strong class="big-number">{step === 0 ? '...' : '01'}</strong><p>item to review</p><div class="scan-bars" aria-hidden="true">{#each [65,90,48,76,58,85] as height}<i style={`--bar:${height}%`}></i>{/each}</div><span class="pill">{step > 0 ? 'Scan finished' : 'Collecting signals…'}</span></aside><div class="finding"><span class="micro">{step < 2 ? 'FINDING' : 'VERIFIED RECOMMENDATION'}</span><h5>{step === 0 ? 'Looking for the useful fixes.' : 'Make the page title clearer.'}</h5><div class="search-result"><small>example.com / services</small><strong>{step >= 2 ? 'Local hauling & cleanup | Example Co.' : 'Services | Home'}</strong><p>Pickup, hauling and site cleanup for local projects.</p></div>{#if step >= 1}<div class="checkline">✓ Source: page title + search data</div>{/if}{#if step >= 2}<div class="checkline">✓ Verifier: recommendation is grounded</div>{/if}{#if step === 3}<div class="approval">Ready for human review <span>Approve draft ↗</span></div>{/if}</div></div>
   {:else if slug === 'clearpoint'}
    <div class="aero"><div class="tiny-nav">CLEARPOINT AERO <span>SERVICES {step === 1 ? '−' : '+'}</span></div>{#if step === 1}<div class="mega"><strong>Detect & assess</strong><strong>Plan & protect</strong><strong>Train & respond</strong></div>{/if}<div class="radar" aria-hidden="true"><i></i><b>+</b></div><h5>Know what’s<br/>in your airspace.</h5><p>From detection to a plan you can act on.</p><div class="process">{#each ['Assess','Design','Deploy','Train','Support'] as s, i}<span class:selected={i === (step >= 2 ? 2 : 0)}>{i + 1} {s}</span>{/each}</div></div>
   {:else if slug === 'ops-tasks'}
    <div class="task-app"><div><span class="micro">TODAY, MADE SIMPLE</span><h5>Let’s get<br/>this shipped.</h5><div class="bubble user">Help me launch the new client site.</div></div><div class="task-list"><span class="micro">{step >= 2 ? '✓ PLAN CHECKED' : 'YOUR PLAN'}</span>{#each ['Check mobile layouts','Test the contact form','Connect the domain','Confirm analytics'] as task, i}<div class="task" class:revealed={step >= 1} class:checked={step === 3 && i < 2}><span>{step === 3 && i < 2 ? '✓' : '○'}</span>{step >= 1 ? task : 'Waiting for your plan…'}</div>{/each}</div></div>
   {:else if slug === 'kalama'}
    <div class="migration"><div class="design-site"><div class="tiny-nav">KALAMA SILVAS <span>SELECTED WORK</span></div><div class="architecture" aria-hidden="true"><i></i><i></i><i></i></div><h5>Spaces with<br/>a point of view.</h5></div><aside><span class="micro">MIGRATION CHECKLIST</span>{#each ['Site rebuilt','Cloudflare connected','Old URLs redirected','Canonical site verified'] as item, i}<div class="task" class:checked={i <= step}><span>{i <= step ? '✓' : '○'}</span>{item}</div>{/each}<div class="route">/old-project <span>→ 301 →</span> /work</div></aside></div>
   {:else if slug === 'vault-mcp'}
    <div class="vault"><div class="access-node"><span class="symbol">↗</span><strong>AI tool</strong><span>Requests a connection</span></div><div class="connection" class:connected={step >= 1}>······</div><div class="safe"><span class="symbol">{step >= 2 ? '✓' : '◈'}</span><strong>Scoped vault</strong><span>{step >= 2 ? 'Contractor scope checked' : 'Waiting for authorization'}</span><div class="secret">•••• •••• ••••</div></div><div class="connection" class:connected={step === 3}>······</div><div class="access-node"><span class="symbol">{step === 3 ? '✓' : '○'}</span><strong>Allowed service</strong><span>{step === 3 ? 'Connected securely' : 'No access yet'}</span></div></div>
   {:else if slug === 'inbox'}
    <div class="split"><aside class="threads"><span class="micro">TEAM INBOX</span><div class="thread selected"><b>Sample customer</b><span>Incoming call</span><small>Just now</small></div><div class="thread"><b>Yesterday’s pickup</b><span>Thanks for the help!</span></div><div class="thread"><b>Site cleanup</b><span>Estimate requested</span></div></aside><div class="conversation"><div class="tiny-nav">SAMPLE CUSTOMER <span>{step >= 2 ? 'CLAIMED' : 'UNASSIGNED'}</span></div><div class="bubble user">Can you help with a pickup Friday?</div><div class="call"><span class="symbol">☎</span><strong>{step === 0 ? 'Incoming call' : step === 1 ? 'Ringing teammate 1…' : 'Answered by Alex'}</strong></div>{#if step >= 2}<div class="ownership">✓ Alex owns this conversation</div>{/if}{#if step === 3}<div class="bubble assistant">Pickup confirmed. The team can see it’s handled.</div>{/if}</div></div>
   {:else if slug === 'crew'}
    <div class="crew-board"><aside><span class="micro">CREW</span>{#each ['Research','Build','Review'] as name, i}<div class="agent"><span>{name[0]}</span><strong>{name}</strong><small>{i === 0 ? 'Working' : 'Available'}</small></div>{/each}</aside><div class="job"><span class="micro">SCHEDULED JOB / 001</span><h5>Research the next<br/>client project.</h5><div class="checkpoint"><span>Progress saved</span><strong>{step === 0 ? '0' : step === 1 ? '2' : step === 2 ? '2' : '4'} / 4</strong></div><div class="track"><i style={`width:${[4,50,50,100][step]}%`}></i></div><div class="job-event">{['Queued for Research','Checkpoint saved · step 2','Worker interrupted → resumed from step 2','✓ Finished · result ready'][step]}</div></div></div>
   {:else if slug === 'outbound'}
    <div class="dispatch"><div><span class="micro">CALL QUEUE</span><h5>Good timing<br/>is a feature.</h5><div class="queue-row"><span>Sample call #001</span><b>{step === 3 ? 'Dispatched ↗' : 'Pending'}</b></div><div class="queue-row muted"><span>Sample call #002</span><b>Outside calling hours</b></div></div><div class="gates">{#each ['Valid signed request','Within calling window','Attempts below limit','Capacity reserved'] as gate, i}<div class="task" class:checked={i <= step}><span>{i <= step ? '✓' : '○'}</span>{gate}</div>{/each}<div class="pill">{step === 3 ? '✓ Status synced to Airtable' : 'Checks before dispatch'}</div></div></div>
   {:else}
    <div class="portfolio-demo"><div class="mini-portfolio" class:print={step === 3}><div class="tiny-nav">BRAYDEN. <span>{step === 3 ? 'RESUME' : 'SEE THE WORK ↗'}</span></div>{#if step === 3}<h5>Brayden Gregersen</h5><p>Frontend engineer</p>{#each ['Experience','Education','Skills'] as label}<div class="resume-line"><b>{label}</b><i></i><i></i></div>{/each}{:else}<div class="mini-hero"><h5>{step === 0 ? 'I build sites people can actually run.' : 'Here’s what I’ve built.'}</h5><span class="mini-cube" aria-hidden="true">B.</span></div><div class="mini-band">{step >= 2 ? 'CHAT CMS −' : 'FROM MACHINES TO SOFTWARE.'}</div>{#if step === 2}<p class="mini-detail">A simpler way for a business owner to update a website.</p>{/if}{/if}</div><span class="page-badge">{step === 3 ? '1 clean page' : 'Built to explore'}</span></div>
   {/if}
  </div>
 </div>
 <div class="scene-bottom"><p>{concept.notes[step]}</p><div class="controls"><button onclick={toggle} aria-label={`${playing ? 'Pause' : 'Play'} ${title} demo`}>{playing ? 'Ⅱ Pause' : '▶ Play'}</button><button onclick={next} aria-label={`Next step in ${title} demo`}>Next →</button><button onclick={replay} aria-label={`Replay ${title} demo`}>↻ Replay</button></div></div>
</section>

